int refine = refine_choices[(int)(*FUZZ_PARAM(unsigned int)%3)];
double scale = (double)((*FUZZ_PARAM(unsigned int)%200)+1)/250.0; // (0, ~0.8]
double sigma_scale = (double)((*FUZZ_PARAM(unsigned int)%200)+1)/200.0; // >0
double quant = (double)((*FUZZ_PARAM(unsigned int)%400)+1)/10.0;
double ang_th = (double)((*FUZZ_PARAM(unsigned int)%900)+1)/10.0; // degrees
double log_eps = (double)(*FUZZ_PARAM(int)%2000)/10.0; // can be negative/positive
double density_th = (double)((*FUZZ_PARAM(unsigned int)%1000)+1)/1000.0; // (0,1]
int n_bins = (int)(*FUZZ_PARAM(unsigned int)%2048 + 1);
cv::Ptr<cv::LineSegmentDetector> lsd = cv::createLineSegmentDetector(refine, scale, sigma_scale, quant, ang_th, log_eps, density_th, n_bins);
if (!lsd) { FUZZ_BAIL(); }
// Prepare a grayscale image for detection
int rows = (int)(*FUZZ_PARAM(unsigned int)%180 + 32);
int cols = (int)(*FUZZ_PARAM(unsigned int)%180 + 32);
cv::Mat gray(rows, cols, CV_8UC1); cv::randu(gray, 0, 255);
cv::Mat lines, width, prec, nfa;
lsd->detect(gray, lines, width, prec, nfa);
// Draw detected segments onto a color image buffer to exercise drawing path
cv::Mat canvas(rows, cols, CV_8UC3); cv::randu(canvas, 0, 255);
lsd->drawSegments(canvas, lines);
// Compare the same set of segments to itself; result is implementation-defined but should be non-negative
int cmp = lsd->compareSegments(cv::Size(cols, rows), lines, lines, canvas);
